/* Existing presentation is retained in views.js. Authoritative data and every
 * mutation come from the typed API client; only theme/sidebar are local. */
let assets=[],state=null,selectedAsset='D04',selectedScenario='D04',rainfall=20,currentBudget=10,plan=[],comparisonPlan=[],simResult=null,mapFilter='All',selectedGraph='D04',guidedStep=0,toastTimer,assetSort='id',assetSortDir=1;
let appState={reports:[],submitted:[],incidents:[],weights:{},simAffected:[],pulseHistory:[],pulseReasons:[],householdClusters:[]};
let budgetResult=null,alternativeResult=null,assetPage=1,reportPage=1,incidentPage=1,traceCache=new Map(),whatTimer,weightTimer,searchTimer,refreshing=false;
let activeMapLayers={roads:true,drainage:true,water:true,reports:true,incidents:true},scenarioFacility=null;
const defaultWeights={condition:.22,population:.20,service:.18,accessibility:.15,hazard:.15,evidence:.10};
const scenarios=[{id:'D04',name:'Drain D04 blocked',detail:'Ward 4 · directed dependency cascade',label:'CRITICAL'},{id:'R07',name:'Road R07 blocked',detail:'Road access disruption',label:'HIGH'},{id:'W02',name:'Water Tank W02 unavailable',detail:'Connected supply points',label:'HIGH'},{id:'rain',name:'Heavy rainfall',detail:'Hazard threshold and drainage exposure',label:'HAZARD'},{id:'power',name:'Power disruption',detail:'Water pumps and streetlights',label:'HAZARD'},{id:'supply',name:'Water supply interruption',detail:'All village tanks',label:'HIGH'},{id:'multi',name:'Multiple simultaneous failures',detail:'D04 + R07 + W02',label:'COMPOUND'},{id:'custom',name:'Custom asset failure',detail:'Enter one or more asset IDs',label:'CUSTOM'}];
function $(x){return document.getElementById(x)||document.querySelector(x)}
const scoreOf=a=>a?.critical??0,riskOf=a=>a?.risk||'Low',healthFor=t=>state?.categories[t]??0,pulseScore=()=>state?.pulse??0,allReports=()=>state?.reports||[],linkedReportCount=a=>allReports().filter(r=>r.assetId===a.id).length,addEdges=()=>state?.dependencies||[];
const traceFrom=id=>traceCache.get(id)||{ids:[],depth:0};
function failure(error){if(error.status===401){showLogin();return}toast(error.message||'The request failed. Please retry.');const el=$('formError');if(el)el.textContent=error.message;}
async function action(fn,button){if(button?.disabled)return;const text=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…'}try{return await fn()}catch(e){failure(e)}finally{if(button){button.disabled=false;button.textContent=text}}}
async function mutation(route,method,body){const result=await api.request(route,method,body);await refresh();return result}
function modal(title,body,eyebrow='GRAM-PULSE'){ $('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=body;$('modal').classList.add('show')}
function overlay(html){let el=$('serviceOverlay');if(!el){el=document.createElement('div');el.id='serviceOverlay';el.style.cssText='position:fixed;inset:0;z-index:100;background:var(--paper);display:grid;place-items:center;padding:20px;overflow:auto';document.body.append(el)}el.innerHTML=`<div class="card panel" style="width:min(440px,100%);margin:auto"><div class="brand">GRAM-<b>PULSE</b></div>${html}</div>`;document.querySelector('.shell').hidden=true;return el}
function showLogin(){overlay('<h2 style="margin:20px 0 6px">Sign in</h2><p class="panel-sub">Predictive Rural Infrastructure Digital Twin</p><form id="loginForm" style="display:grid;gap:12px;margin-top:20px"><label>Email<input class="input" id="loginEmail" type="email" autocomplete="username" required style="width:100%"></label><label>Password<input class="input" id="loginPassword" type="password" autocomplete="current-password" required style="width:100%"></label><div id="formError" role="alert" class="risk-high"></div><button class="btn primary">Sign in</button></form><div class="notice" style="margin-top:18px">SIMULATED / DEMO DATA<br>Use the account credentials configured during database seeding.</div>');$('loginForm').onsubmit=e=>{e.preventDefault();action(async()=>{await api.login($('loginEmail').value,$('loginPassword').value);await refresh(true)},e.submitter)}}
async function boot(){overlay('<p style="margin:20px 0">Connecting to GRAM-PULSE services…</p>');try{await api.authenticate();await refresh(true)}catch(e){if(e.status===401)showLogin();else offline(e)}}
function offline(e){const message=e?.message||'The API did not return a usable response.';const code=e?.code||'SERVICE_UNAVAILABLE';overlay(`<h2 style="margin:20px 0">Unable to connect to GRAM-PULSE services</h2><p role="alert">${esc(message)}</p><p class="panel-sub">Error code: ${esc(code)}${e?.status?` · HTTP ${e.status}`:''}</p><button id="retryServices" class="btn primary" onclick="retryServices()" style="margin-top:18px">Retry</button>`)}
async function retryServices(){const button=$('retryServices');if(button){button.disabled=true;button.textContent='Checking services…'}try{await api.authenticate();await refresh(true)}catch(e){if(e.status===401)showLogin();else offline(e)}}
function hydrate(s){state=s;assets=s.assets;simResult=s.simulation;appState={reports:s.reports,submitted:s.reports.filter(r=>r.userId===s.user.id),incidents:s.incidents,weights:s.weights,simAffected:s.simAffected,pulseHistory:s.pulseHistory,pulseReasons:[s.pulseHistory.at(-1)?.reason||'Database calculations'],householdClusters:s.wards};traceCache.clear();}
async function refresh(initial=false){if(refreshing)return;refreshing=true;try{const fresh=await api.state();const dataChanged=state&&fresh.revision!==state.revision;hydrate(fresh);$('serviceOverlay')?.remove();document.querySelector('.shell').hidden=false;const previous=$('whatAsset').value;for(const id of ['whatAsset','citizenAsset']){const select=$(id),keep=select.value;select.innerHTML=(id==='citizenAsset'?'<option value="">Auto-associate by category and ward</option>':'')+assets.map(a=>`<option value="${a.id}">${esc(a.id+' · '+a.name)}</option>`).join('');if(assets.some(a=>a.id===keep))select.value=keep;}if(!previous&&assets.some(a=>a.id==='D04'))$('whatAsset').value='D04';const types=$('assetTypeFilter'),keep=types.value;types.innerHTML='<option value="all">All types</option>'+[...new Set(assets.map(a=>a.type))].map(t=>`<option>${esc(t)}</option>`).join('');types.value=keep||'all';renderKpis();renderPulse();renderTwinSummary();renderMap('mapDash');renderMap('mapTwin');renderOwnReports();renderConfidence();applyRoles();if(initial)go(location.hash.slice(1)||'dashboard');else await renderCurrent();$('accountLabel').textContent=state.user.name+' · '+state.user.role;$('mapCaption').textContent=state.village.name+' · '+state.wards.length+' wards · '+assets.length+' database assets · schematic, not to scale';if(dataChanged){budgetResult=null;alternativeResult=null;plan=[];comparisonPlan=[];if($('budget').classList.contains('active')){renderPlan();$('planCaption').textContent='Data updated. Generate a plan using the latest records.';}}}finally{refreshing=false}}
function applyRoles(){const admin=state.user.role==='admin',officer=state.user.role==='officer';const restricted=['simulate','budget','whatif','settings','management','audit'];document.querySelectorAll('#nav [data-page]').forEach(b=>b.hidden=(!admin&&restricted.includes(b.dataset.page))||(!admin&&!officer&&b.dataset.page==='incidents'));document.querySelectorAll('[onclick^="openAssetForm"],[onclick^="deleteAsset"]').forEach(b=>b.hidden=!admin);}
function permitted(id){return state.user.role==='admin'||(!['simulate','budget','whatif','settings','management','audit'].includes(id)&&(state.user.role==='officer'||id!=='incidents'))}
function go(id){if(!state)return;const page=$(id);if(!page?.classList.contains('page')){modal('Page not found','<p>The requested page does not exist.</p><button class="btn" onclick="closeModal();go(\'dashboard\')">Open dashboard</button>','404');return}if(!permitted(id)){modal('Access restricted','<p>Your role does not have access to this page.</p>','UNAUTHORIZED');return}document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('#nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$('sidebar').classList.remove('open');if(location.hash!=='#'+id)history.pushState(null,'','#'+id);window.scrollTo(0,0);action(renderCurrent);}
async function renderCurrent(){const id=document.querySelector('.page.active')?.id;if(id==='assets')await renderAssetTable();if(id==='reports')await renderReports();if(id==='incidents')await renderIncidents();if(id==='priorities')await renderPriorities();if(id==='twin'){renderMap('mapTwin');await renderDependencyGraph()}if(id==='simulate')renderSimulation();if(id==='analytics')renderAnalytics();if(id==='confidence')renderConfidence();if(id==='citizen')renderOwnReports();if(id==='settings')renderWeightControls();if(id==='brief')generateBrief();if(id==='whatif')calculateWhatIf();if(id==='budget')renderPlan();if(id==='management')await renderManagement();if(id==='audit')await renderAudit();}
function pager(host,p,callback){let el=$(host+'Pager');if(!el){el=document.createElement('div');el.id=host+'Pager';el.className='toolbar';$(host).closest('table')?.parentElement.after(el);if(!el.parentElement)$(host).after(el)}el.innerHTML=`<button class="btn small" ${p.page<=1?'disabled':''} onclick="${callback}(${p.page-1})">Previous</button><span class="panel-sub">${p.total} records · page ${p.page} / ${Math.max(1,Math.ceil(p.total/p.pageSize))}</span><button class="btn small" ${p.page*p.pageSize>=p.total?'disabled':''} onclick="${callback}(${p.page+1})">Next</button>`}
async function renderAssetTable(){try{const q=new URLSearchParams({q:$('assetSearch').value,page:assetPage,pageSize:25,sort:assetSort,direction:assetSortDir===1?'asc':'desc'});if($('assetTypeFilter').value!=='all')q.set('type',$('assetTypeFilter').value);if($('assetWardFilter').value!=='all')q.set('ward',$('assetWardFilter').value);const r=await api.page('/assets?'+q);$('assetCount').textContent=r.pagination.total+' assets';$('assetRows').innerHTML=r.data.map(a=>`<tr><td><button class="linkbtn" onclick="inspectAsset('${a.id}')">${esc(a.id+' · '+a.name)}</button></td><td>${esc(a.type)}</td><td>${a.ward}</td><td>${a.condition}</td><td>${a.critical}</td><td>${a.risk}</td><td>${fmt(a.pop)}</td><td>${money(a.cost)}</td><td>${state.user.role==='admin'?`<button class="linkbtn" onclick="openAssetForm('${a.id}')">Edit</button><button class="linkbtn" onclick="deleteAsset('${a.id}')">Delete</button>`:'View only'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No matching assets.</td></tr>';pager('assetRows',r.pagination,'changeAssetPage')}catch(e){$('assetRows').innerHTML='<tr><td colspan="9">Unable to load assets. <button class="btn" onclick="renderAssetTable()">Retry</button></td></tr>';failure(e)}}
function changeAssetPage(p){assetPage=p;renderAssetTable()}
async function inspectAsset(id){await action(async()=>{const a=await api.request('/assets/'+id);const index=assets.findIndex(x=>x.id===id);if(index>=0)assets[index]=a;else assets.push(a);await loadTrace(id);openAsset(id);applyRoles()})}
async function loadTrace(id){const t=await api.request('/trace/'+id);traceCache.set(id,{...t,ids:t.affected});return t}
function saveAsset(e,id){e.preventDefault();action(async()=>{const input={name:$('fName').value,type:$('fType').value,ward:Number($('fWard').value),condition:Number($('fCondition').value),pop:Number($('fPopulation').value),cost:Number($('fCost').value),hazard:Number($('fHazard').value),action:$('fAction').value};const extra=readForm(e.target,['latitude','longitude','capacity','accessibility']);Object.assign(input,extra);if(input.source==='VERIFIED')input.verifiedAt=new Date().toISOString();const connections=$('fConnection').value.split(',').map(x=>x.trim()).filter(Boolean);if(connections.some(id=>!assets.some(a=>a.id===id)))throw Error('A connected asset was not found.');input.connections=connections;await mutation('/assets'+(id?'/'+id:''),id?'PATCH':'POST',input);closeModal();toast('Asset saved to database')},e.submitter)}
function deleteAsset(id){if(confirm('Delete '+id+'? Assets with incident or intervention history must be retired instead.'))action(async()=>{await mutation('/assets/'+id,'DELETE');toast('Asset deleted')})}
async function renderPriorities(){const rows=assets.filter(a=>($('priorityType').value==='all'||a.type===$('priorityType').value)&&($('priorityRisk').value==='all'||a.risk===$('priorityRisk').value)&&(!$('priorityWard')||$('priorityWard').value==='all'||a.ward===Number($('priorityWard').value))).sort((a,b)=>b.critical-a.critical);$('priorityRows').innerHTML=rows.map((a,i)=>`<tr class="clickable" onclick="inspectAsset('${a.id}')"><td>${i+1}. ${a.id}</td><td>${esc(a.type)}</td><td>${a.condition}</td><td>${a.critical}</td><td>${fmt(a.pop)}</td><td>${a.risk}</td><td>${a.confidence}%</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No matching priorities.</td></tr>'}
function explainAsset(id){const a=byId(id);modal('Why '+a.name+' · '+a.critical+'/100',a.reason.map(([label,value])=>`<div class="reason"><span>${esc(label)}</span><b>+${value}</b></div>`).join('')+'<div class="notice">Server-calculated normalized weighted sum. Open complaints, incidents and the active scenario feed the factors. SIMULATED model; contributions sum to the score.</div>','EXPLAINABLE CRITICALITY')}
function renderTwinSummary(){$('twinSummary').innerHTML=[...new Set(assets.map(a=>a.type))].map(t=>`<div class="conf-source"><span>${esc(t)}</span><b>${assets.filter(a=>a.type===t).length} assets</b></div>`).join('')}
function mapSvg(){const filtered=assets.filter(a=>mapFilter==='All'||mapFilter==='Citizen Reports'&&a.reports>0||mapFilter==='Critical Assets'&&a.risk==='High'||a.type===mapFilter);return `<svg viewBox="0 0 1000 580" preserveAspectRatio="none"><rect width="1000" height="580" fill="#edf2ea"/>${state.wards.map(w=>`<polygon class="ward" points="${w.geometry.map(p=>`${p[0]*10},${p[1]*5.8}`).join(' ')}"/><text class="map-label" x="${w.geometry[0][0]*10+10}" y="${w.geometry[0][1]*5.8+20}">${esc(w.name)}</text>`).join('')}${activeMapLayers.roads?assets.filter(a=>a.type==='Road').map(a=>`<line class="map-road-edge" x1="${a.x*10-20}" y1="${a.y*5.8}" x2="${a.x*10+20}" y2="${a.y*5.8}"/>`).join(''):''}${filtered.filter(a=>a.cat!=='drainage'||activeMapLayers.drainage).filter(a=>a.cat!=='water'||activeMapLayers.water).map(a=>`<circle class="asset-node ${a.cat} ${appState.simAffected.includes(a.id)||window.activeTrace?.includes(a.id)?'focus':''}" cx="${a.x*10}" cy="${a.y*5.8}" r="${a.risk==='High'?7:5}" style="opacity:${window.activeWard&&window.activeWard!=='all'&&Number(window.activeWard)!==a.ward||window.activeRisk&&window.activeRisk!=='all'&&window.activeRisk!==a.risk?.12:1}" onclick="inspectAsset('${a.id}')"><title>${esc(a.id+' · '+a.name+' · priority '+a.critical)}</title></circle>`).join('')}${activeMapLayers.reports?reportClusters().map(c=>{const a=byId(c.assetId);return a?`<circle class="report-cluster" cx="${a.x*10+8}" cy="${a.y*5.8+8}" r="${Math.min(15,5+c.reports.length)}" onclick="openReportCluster('${esc(c.key)}')"><title>${c.reports.length} reports</title></circle>`:''}).join(''):''}${activeMapLayers.incidents?appState.incidents.filter(i=>i.status!=='Resolved').map(i=>{const a=byId(i.assetId);return a?`<text x="${a.x*10}" y="${a.y*5.8-12}" fill="#b43d31" style="cursor:pointer" onclick="inspectAsset('${a.id}')">⚠<title>${esc(i.id)}</title></text>`:''}).join(''):''}<text class="map-label" x="850" y="565">SCHEMATIC · DEMO · N ↑</text></svg>`}
function renderMap(id){const el=$(id);if(!el||!state)return;el.innerHTML=mapSvg()+`<div class="map-controls"><button class="filter" onclick="zoomMap(1.15,'${id}')">＋</button><button class="filter" onclick="zoomMap(.87,'${id}')">−</button><button class="filter" onclick="resetMapView('${id}')">Reset</button><select class="filter" onchange="setMapFilter(this.value)">${['All','Road','Water','Drainage','Education','Healthcare','Streetlight','Sanitation','Public Facility','Critical Assets','Citizen Reports'].map(t=>`<option ${t===mapFilter?'selected':''}>${t}</option>`).join('')}</select><select class="filter" onchange="setWardFilter(this.value)"><option value="all">All wards</option>${state.wards.map(w=>`<option value="${w.number}" ${window.activeWard===String(w.number)?'selected':''}>${esc(w.name)}</option>`).join('')}</select><select class="filter" onchange="setRiskFilter(this.value)"><option value="all">All risk</option>${['High','Medium','Low'].map(t=>`<option ${window.activeRisk===t?'selected':''}>${t}</option>`).join('')}</select>${Object.entries(activeMapLayers).map(([k,v])=>`<label class="filter"><input type="checkbox" ${v?'checked':''} onchange="toggleMapLayer('${k}',this.checked,'${id}')">${k}</label>`).join('')}</div><div class="map-legend">${assets.length} database assets · ${state.simAffected.length} simulated impacts · click to inspect</div>`;enableMapPan(el.querySelector('svg'))}
function setWardFilter(v){window.activeWard=v;renderMap('mapDash');renderMap('mapTwin')}function setRiskFilter(v){window.activeRisk=v;renderMap('mapDash');renderMap('mapTwin')}function toggleMapLayer(k,v,id){activeMapLayers[k]=v;renderMap(id)}
async function renderDependencyGraph(){if(!state)return;const t=byId(selectedGraph)?await loadTrace(selectedGraph):null;const q=($('graphSearch')?.value||'').toLowerCase(),type=$('graphType')?.value||'all';const nodes=assets.filter(a=>!q||`${a.id} ${a.name}`.toLowerCase().includes(q));const points=new Map(nodes.map((a,i)=>[a.id,{x:25+(i%8)*180,y:35+Math.floor(i/8)*85}]));const edges=state.dependencies.filter(e=>points.has(e.source)&&points.has(e.target)&&(type==='all'||e.type===type));const height=Math.ceil(nodes.length/8)*85+70;$('dependencyGraph').innerHTML=`<svg id="graphSvg" viewBox="0 0 1480 ${height}" style="width:1480px;height:${height}px;max-width:none"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#8ba99a"/></marker></defs>${edges.map(e=>{let a=points.get(e.source),b=points.get(e.target);return`<path class="graph-link" d="M${a.x+145} ${a.y+23} L${b.x} ${b.y+23}"><title>${esc(e.type)} · strength ${e.strength}</title></path>`}).join('')}${nodes.map(a=>{const p=points.get(a.id);return`<g class="graph-node ${a.id===selectedGraph?'selected':''} ${state.simAffected.includes(a.id)||window.activeTrace?.includes(a.id)?'focus':''}" onclick="selectGraphNode('${a.id}')" transform="translate(${p.x},${p.y})"><rect width="145" height="48"/><text x="8" y="18">${esc(a.id+' · '+a.name.slice(0,15))}</text><text class="subtext" x="8" y="35">${a.critical} · ${esc(a.type)}</text></g>`}).join('')}</svg>`;enableMapPan($('graphSvg'));$('graphDetails').innerHTML=t?`<div class="panel-title">${esc(selectedGraph)} · ${t.affected.length} affected nodes · depth ${t.depth}</div><p class="panel-sub">${t.pop} residents · ${t.households} households · directed relationships</p><div class="toolbar"><button class="btn" onclick="traceImpact('${selectedGraph}')">Trace impact</button><button class="btn" onclick="inspectAsset('${selectedGraph}')">Inspect</button></div><p class="panel-sub">Outgoing: ${state.dependencies.filter(e=>e.source===selectedGraph).map(e=>esc(e.type+' → '+e.target)).join(', ')||'None'}<br>Incoming: ${state.dependencies.filter(e=>e.target===selectedGraph).map(e=>esc(e.source+' → '+e.type)).join(', ')||'None'}</p>`:'<div class="empty">Select an asset to trace dependencies.</div>'}
async function selectGraphNode(id){selectedGraph=id;await action(async()=>{const t=await loadTrace(id);window.activeTrace=t.affected;await renderDependencyGraph();renderMap('mapTwin')})}
function traceImpact(id){closeModal();go('twin');selectGraphNode(id)}function miniGraph(){return '<div class="notice">Open the dependency graph to inspect server-stored relationships and trace impacts.</div><button class="btn" onclick="go(\'twin\')">Open graph</button>'}
function runSimulation(){action(async()=>{let assetIds=[];if(selectedScenario==='custom'){const ids=prompt('Enter asset IDs separated by commas (for example D04,R07)');if(!ids)return;assetIds=ids.split(',').map(s=>s.trim())}$('simulationResult').innerHTML='<div class="empty">Calculating dependency propagation…</div>';simResult=await api.request('/simulations/failure','POST',{scenario:selectedScenario,assetIds,rain:rainfall,apply:true});await refresh();showSimulationResult();toast('Simulation saved; dashboard and priorities updated')})}
function resetSimulation(){action(async()=>{await mutation('/simulations/active','DELETE');simResult=null;window.activeTrace=[];renderSimulation();toast('Scenario cleared')})}function setScenario(id){selectedScenario=id;go('simulate');runSimulation()}
async function buildBudgetPlan(strategy='impact'){if(!state||state.user.role!=='admin')return;await action(async()=>{currentBudget=Number($('budgetRange').value);$('planCaption').textContent='Optimizing database interventions…';const input={budget:currentBudget,minProjects:Number($('minProjects').value),maxProjects:Number($('maxProjects').value),minimumPriority:Number($('minimumPriority').value),strategy};if($('budgetWard').value)input.ward=Number($('budgetWard').value);if($('budgetCategory').value)input.category=$('budgetCategory').value;const result=await api.request('/budget/optimize','POST',input);if(strategy==='cost'){alternativeResult=result;comparisonPlan=result.projects.map(p=>({...byId(p.assetId),cost:p.cost,action:p.name,benefit:p.value}));}else{budgetResult=result;plan=result.projects.map(p=>({...byId(p.assetId),cost:p.cost,action:p.name,benefit:p.value}));}renderPlan();renderComparison();if(!result.feasible)$('planCaption').textContent=result.reason})}
function planStats(p){const r=p===comparisonPlan?alternativeResult:budgetResult;return r?{spend:r.totalCost,residents:r.residents,risk:r.risk,critical:p.filter(a=>a.critical>=65).length,services:r.services}:{spend:0,residents:0,risk:0,critical:0,services:0}}
function renderComparison(){const show=r=>r?`<div>Cost ${money(r.totalCost)} · ${r.residents} residents<br>Risk reduction ${r.risk}% · ${r.services} service types<br>Ward coverage ${r.wardCoverage.join(', ')||'None'}</div>`:'Generate this plan to compare.';$('comparison').innerHTML=`<div class="grid half"><div class="budget-box"><b>Cost-first alternative</b>${show(alternativeResult)}<button class="btn small" onclick="showAlternative()">Calculate alternative</button></div><div class="budget-box"><b>Optimized impact</b>${show(budgetResult)}</div></div><p class="panel-sub">Exact 0/1 selection from database projects. Population uses ward-max catchments to limit overlap; benefits remain modeled.</p>`}
function showAlternative(){buildBudgetPlan('cost')}
function saveCitizenReport(e){e.preventDefault();action(async()=>{let imageId=null;const file=$('citizenPhoto').files[0];if(file)imageId=(await api.upload(file)).id;const r=await mutation('/reports','POST',{name:$('citizenName').value,category:$('citizenCategory').value,description:$('citizenDescription').value,ward:Number($('citizenWard').value),assetId:$('citizenAsset').value||null,imageId});$('citizenForm').reset();$('photoPreview').innerHTML='';modal('Report recorded · '+r.id,`<div class="notice">Saved to the database. Awaiting verification.</div><div class="detail-grid"><div class="detail-item"><span>Severity</span><b>${r.severity}</b></div><div class="detail-item"><span>Classification confidence</span><b>${r.confidence}%</b></div></div><p>${esc(r.classificationMethod)}</p><button class="btn" onclick="closeModal();go('reports')">View report</button>`,'REPORT SAVED')},e.submitter)}
async function renderReports(){try{const r=await api.page('/reports?page='+reportPage+'&pageSize=20');$('reportList').innerHTML=r.data.map(r=>`<div class="report"><div><strong>${esc(r.id)} · ${esc(r.category)} · ${esc(r.assetId||'Unassociated')}</strong><p>${esc(r.description)}</p><p>${esc(r.status)} · ${r.synthetic?'SIMULATED':'FIELD REPORTED'} · ${new Date(r.timestamp).toLocaleString()}</p>${r.photo?`<img src="${r.photo}" alt="Report evidence" style="max-width:160px;max-height:120px">`:''}<div class="toolbar"><button class="btn small" onclick="editReport('${r.id}')">${state.user.role==='citizen'?'Edit description':'Manage report'}</button>${r.assetId?`<button class="linkbtn" onclick="inspectAsset('${r.assetId}')">Inspect asset</button>`:''}</div></div><span class="pill ${r.severity==='HIGH'?'high':'medium'}">${r.severity}</span></div>`).join('')||'<div class="empty">No reports available for your account.</div>';pager('reportList',r.pagination,'changeReportPage');$('clusterList').innerHTML=reportClusters().map(c=>`<div class="report"><div><strong>Ward ${c.ward} · ${esc(c.category)}</strong><p>${c.reports.length} reports</p><button class="linkbtn" onclick="openReportCluster('${esc(c.key)}')">Inspect cluster</button></div></div>`).join('');const values=$('reports').querySelectorAll('.kpis .value');[r.pagination.total,reportClusters().length,state.reports.filter(r=>r.severity==='HIGH').length].forEach((n,i)=>{if(values[i])values[i].textContent=n})}catch(e){$('reportList').innerHTML='<div class="empty">Unable to load reports. <button class="btn" onclick="renderReports()">Retry</button></div>';failure(e)}}
