function editReport(id){const r=state.reports.find(r=>r.id===id);if(!r)return;modal('Manage '+r.id,`<form id="reportEdit"><label>Description<textarea class="input" name="description" required minlength="8" style="width:100%">${esc(r.description)}</textarea></label>${state.user.role!=='citizen'?`<label>Status<select name="status" class="select">${['Pending verification','Verified','Assigned','In Progress','Resolved','Rejected'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Resolution<textarea name="resolutionNotes" class="input">${esc(r.resolutionNotes)}</textarea></label>${state.user.role==='admin'?`<label>Assigned officer ID<input class="input" name="assignedOfficer" value="${esc(r.assignedOfficer||'')}" placeholder="officer"></label>`:''}`:''}<div id="formError" role="alert"></div><button class="btn primary">Save</button></form>`);$('reportEdit').onsubmit=e=>{e.preventDefault();action(async()=>{const body=Object.fromEntries(new FormData(e.target));if('assignedOfficer'in body)body.assignedOfficer=body.assignedOfficer||null;await mutation('/reports/'+id,'PATCH',body);closeModal();toast('Report updated')},e.submitter)}}
