function calculateWhatIf(){clearTimeout(whatTimer);whatTimer=setTimeout(()=>action(async()=>{const input={rain:Number($('whatRain').value),population:Number($('whatPopulation').value),assetId:$('whatAsset').value,condition:Number($('whatCondition').value),capacity:Number($('whatCapacity').value)};if(scenarioFacility)input.newFacility=scenarioFacility;if($('relocateAsset').value)input.relocate={assetId:$('relocateAsset').value,latitude:Number($('relocateLat').value),longitude:Number($('relocateLon').value)};$('whatRainLabel').textContent=input.rain+'%';$('whatPopulationLabel').textContent=input.population+'%';$('whatIfResults').innerHTML='<div class="empty">Calculating scenario…</div>';const r=await api.request('/simulations/what-if','POST',input);$('whatIfResults').innerHTML='<div class="impact-kpis">'+Object.keys(r.before).map(k=>`<div class="mini"><span>${esc(k)} · before → after</span><b>${r.before[k]} → ${r.after[k]}</b><small>Δ ${r.delta[k]}</small></div>`).join('')+'</div><div class="notice">'+esc(r.label)+'</div>'}),300)}
