function renderCommandResults(q){clearTimeout(searchTimer);searchTimer=setTimeout(()=>action(async()=>{const records=await api.request('/search?q='+encodeURIComponent(q));const pages=[...document.querySelectorAll('#nav [data-page]')].filter(b=>!b.hidden&&b.textContent.toLowerCase().includes(q.toLowerCase())).map(b=>({kind:'Page',id:b.dataset.page,title:b.textContent,page:b.dataset.page}));const rows=[...pages,...records];$('commandResults').innerHTML=rows.map((r,i)=>`<button class="command-result" data-result="${i}"><span class="command-kind">${esc(r.kind)}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.id)}</small></span></button>`).join('')||'<div class="empty">No matching records.</div>';$('commandResults').querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{const r=rows[i];closeCommand();go(r.page);if(r.kind==='Asset')inspectAsset(r.id);else if(r.kind==='Report')editReport(r.id);else if(r.kind==='Incident'){const i=state.incidents.find(x=>x.id===r.id);modal(r.id,'<p>'+esc(i.description)+'</p><p>'+esc(i.status+' · '+i.severity)+'</p>')}else if(r.kind==='Ward'){const w=state.wards.find(x=>x.id===r.id);modal(w.name,'<p>'+w.population+' residents · '+w.households+' households</p>')}else if(r.kind==='Intervention'&&state.user.role==='admin')editManaged('interventions',r.id)})}),200)}function globalSearch(q){openCommand(q)}function showSearchSuggestions(q){if(q.length>=2)openCommand(q)}
