async function renderManagement(){const kind=$('manageKind').value;let rows;if(kind==='wards')rows=state.wards;else if(kind==='dependencies')rows=state.dependencies;else rows=(await api.page('/'+kind+'?page='+managementPage+'&pageSize=25')).data;$('manageRows').innerHTML=rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.name||r.source+' → '+r.target)}</td><td>${esc(r.status||r.role||r.type||r.population+' residents')}</td><td><button class="linkbtn" onclick="editManaged('${kind}','${r.id}')">Edit</button>${kind==='dependencies'?`<button class="linkbtn" onclick="deleteDependency('${r.id}')">Delete</button>`:''}</td></tr>`).join('')||'<tr><td class="empty">No records.</td></tr>';$('manageAdd').hidden=kind==='wards';$('managementPage').textContent='Page '+managementPage;}
