function profile(){modal('Your profile',`<form id="profileForm">${field('name','Name','text',state.user.name)}<label class="panel-sub">Current password<input class="input" name="currentPassword" type="password" autocomplete="current-password"></label><label class="panel-sub">New password (optional)<input class="input" name="password" type="password" autocomplete="new-password"></label><div id="formError"></div><button class="btn primary">Save profile</button><button type="button" class="btn" onclick="logout()">Sign out</button></form>`);$('profileForm').onsubmit=e=>{e.preventDefault();action(async()=>{const body=readForm(e.target);if(!body.password){delete body.password;delete body.currentPassword}await mutation('/auth/profile','PATCH',body);closeModal();toast('Profile saved')},e.submitter)}}async function logout(){await action(async()=>{await api.logout();state=null;assets=[];closeModal();showLogin()})}
