 $('citizenPhoto').insertAdjacentHTML('afterend','<div id="photoPreview"></div>');$('citizenPhoto').onchange=e=>{const f=e.target.files[0];$('photoPreview').innerHTML='';if(f){const url=URL.createObjectURL(f),img=document.createElement('img');img.src=url;img.alt='Evidence preview';img.style.maxWidth='200px';img.onload=()=>URL.revokeObjectURL(url);$('photoPreview').append(img)}};$('confidenceSelect').onchange=renderConfidence;
 $('assetSearch').oninput=()=>{assetPage=1;clearTimeout(searchTimer);searchTimer=setTimeout(renderAssetTable,250)};for(const id of ['assetTypeFilter','assetWardFilter'])$(id).onchange=()=>{assetPage=1;renderAssetTable()};window.addEventListener('popstate',()=>go(location.hash.slice(1)||'dashboard'));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeCommand()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}});window.addEventListener('unhandledrejection',e=>{e.preventDefault();failure(e.reason)});
