function renderConfidence(){const select=$('confidenceSelect'),keep=select.value;select.innerHTML=assets.map(a=>`<option value="${a.id}">${esc(a.id+' · '+a.name)}</option>`).join('');select.value=byId(keep)?keep:assets[0]?.id||'';const a=byId(select.value);if(!a){$('confAssetTitle').textContent='No assets available';$('confSources').innerHTML='<div class="empty">Add infrastructure to inspect its evidence.</div>';return}$('confAssetTitle').textContent=`${a.id} · ${a.name} · ${a.source}`;$('confScore').textContent=a.confidence+'%';$('confSources').innerHTML=[['Data source',a.source],['Verification date',a.verifiedAt||'Not field verified'],['Linked reports',a.reports],['Classification','Deterministic rules; not trained AI'],['Government / satellite source','Not connected — demo inventory'],...Object.entries(a.confidenceFactors).map(([k,v])=>[k+' contribution','+'+v])].map(([k,v])=>`<div class="conf-source"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');$('confidenceBars').innerHTML=[['High ≥85%',assets.filter(a=>a.confidence>=85).length],['Moderate 50–84%',assets.filter(a=>a.confidence>=50&&a.confidence<85).length],['Limited <50%',assets.filter(a=>a.confidence<50).length]].map(([label,n])=>`<div class="health-item"><div class="health-top"><span>${label}</span><b>${n}</b></div><div class="bar"><i style="width:${n/Math.max(1,assets.length)*100}%"></i></div></div>`).join('')}
