const baseAssetForm=openAssetForm;
openAssetForm=function(id=''){baseAssetForm(id);const a=byId(id);$('fConnection').value=state.dependencies.filter(d=>d.source===id).map(d=>d.target).join(',');const form=$('modalBody').querySelector('form');const fields=document.createElement('div');fields.className='grid half';fields.innerHTML=field('status','Operational status','select',a?.status||'Operational',['Operational','Degraded','Unavailable','Proposed','Retired'])+field('source','Data source','select',a?.source||'FIELD REPORTED',['SIMULATED','FIELD REPORTED','VERIFIED','MODELLED','PREDICTED'])+field('latitude','Latitude','number',a?.latitude||23.012)+field('longitude','Longitude','number',a?.longitude||78.012)+field('capacity','Capacity','number',a?.capacity||100)+field('accessibility','Accessibility (0–100)','number',a?.accessibility||70);form.insertBefore(fields,form.querySelector('button'));};
function renderPlan(){if(!budgetResult){$('planRows').innerHTML='<div class="empty">Generate a plan from current database interventions.</div>';$('planSummary').innerHTML='';renderComparison();return}const r=budgetResult;$('planCaption').textContent=r.feasible?`${r.projects.length} projects · ${money(r.totalCost)} allocated · ${money(r.remainingBudget)} remaining`:r.reason;$('planRows').innerHTML=r.projects.map(p=>`<div class="plan-row"><div><b>${esc(p.name)}</b><p class="panel-sub">${p.assetId} · priority ${scoreOf(byId(p.assetId))} · ${esc(p.status)}</p></div><span>${p.populationBenefit} catchment residents</span><b>${money(p.cost)}</b></div>`).join('')||'<div class="empty">No eligible intervention combination.</div>';$('planSummary').innerHTML='<div class="impact-kpis">'+[['Residents benefited',r.residents],['Mean risk reduction',r.risk+'%'],['Service improvement',(r.serviceImprovement||0)+'%'],['Ward coverage',r.wardCoverage.length]].map(([label,value])=>`<div class="mini"><span>${label}</span><b>${value}</b></div>`).join('')+'</div>';renderComparison()}
function explainPlan(){if(!budgetResult){toast('Generate a budget plan first.');return}modal('Why these interventions?',`<p>${esc(budgetResult.method||budgetResult.reason)}</p><div class="notice">Impact = (0.4 × population benefit + 3 × asset criticality + 2 × risk reduction + service improvement) × confidence / 100. Exact selection respects budget, project counts, ward/category filters and minimum priority.</div>${budgetResult.projects.map(p=>`<div class="reason"><span>${esc(p.name)}</span><b>${p.value} impact units</b></div>`).join('')}`,'BUDGET EXPLANATION')}
function explainPulse(){modal('Village Pulse · '+state.pulse+'/100','<p>Each service category averages condition minus 15% of criticality, with a 20-point penalty for an asset in the active simulated cascade. The six categories have equal weight. Missing categories score zero.</p><div class="notice">The category average is reduced by 0.25 per open incident (up to 10) and 0.08 per unresolved report (up to 10). Results are clamped to 0–100.</div>'+Object.entries(state.categories).map(([k,v])=>`<div class="reason"><span>${k}</span><b>${v}/100</b></div>`).join(''),'TRANSPARENT PULSE MODEL')}
function resetWhatIf(){$('whatRain').value=20;$('whatPopulation').value=0;$('whatCondition').value=0;$('whatCapacity').value=1;$('relocateAsset').value='';scenarioFacility=null;calculateWhatIf()}
const baseAssetTab=showAssetTab;
showAssetTab=function(id,tab){baseAssetTab(id,tab);applyRoles();if(tab==='Dependencies'){const t=traceFrom(id);const values=$('assetTabContent').querySelectorAll('.mini b');if(values[2])values[2].textContent=fmt(t.pop||0)}if(state.user.role!=='admin')$('assetTabContent').querySelectorAll('button[onclick*="runSimulation"]').forEach(b=>b.hidden=true)};
setup();boot();
setInterval(()=>{if(state&&!document.hidden&&!$('modal').classList.contains('show')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))refresh().catch(offline)},20000);

